'use strict';

// MODULES //

var delay = require( 'node:timers/promises' ).setTimeout;
var HarvesterError = require( '@data-apis/errors/harvester-error' );
var limits = require( '@data-apis/limits' );


// FUNCTIONS //

/**
* Returns a bounded retry delay.
*
* @private
* @param {Response|null} response - response
* @param {number} attempt - zero-based attempt
* @returns {number} delay in milliseconds
*/
function retryDelay( response, attempt ) {
	var header = response && response.headers.get( 'retry-after' );

	if ( header && /^\d+$/.test( header ) ) {
		return Math.min( Number( header ) * 1000, 5000 );
	}
	return Math.min( 250 * ( 2 ** attempt ), 2000 );
}

/**
* Cancels a response body before retrying or redirecting.
*
* @private
* @param {Response} response - response
* @returns {Promise<void>} promise
*/
async function cancelBody( response ) {
	if ( response.body ) {
		await response.body.cancel().catch( function ignore() {} );
	}
}

/**
* Tests whether a response indicates provider rate-limit exhaustion.
*
* @private
* @param {Response} response - response
* @returns {boolean} result
*/
function isRateLimited( response ) {
	return response.status === 429 || (
		response.status === 403 && response.headers.get( 'x-ratelimit-remaining' ) === '0'
	);
}

/**
* Returns a provider reset timestamp when supplied.
*
* @private
* @param {Response} response - response
* @returns {string|undefined} RFC 3339 reset timestamp
*/
function rateLimitReset( response ) {
	var value = response.headers.get( 'x-ratelimit-reset' );
	var seconds;
	var date;

	if ( value && /^\d+$/.test( value ) ) {
		seconds = Number( value );
		if ( Number.isSafeInteger( seconds ) ) {
			date = new Date( seconds * 1000 );
			if ( Number.isFinite( date.getTime() ) ) {
				return date.toISOString().replace( '.000Z', 'Z' );
			}
		}
	}
	return undefined;
}

/**
* Reads a response body while enforcing an actual decoded-byte limit.
*
* @private
* @param {Response} response - response
* @param {number} maxBytes - byte limit
* @returns {Promise<Buffer>} body
*/
async function readBoundedBody( response, maxBytes ) {
	var reader;
	var chunks = [];
	var total = 0;
	var item;

	if ( !response.body ) {
		return Buffer.alloc( 0 );
	}
	reader = response.body.getReader();
	try {
		while ( true ) {
			item = await reader.read();
			if ( item.done ) {
				break;
			}
			total += item.value.byteLength;
			if ( total > maxBytes ) {
				await reader.cancel();
				throw new HarvesterError( 'Response exceeded ' + maxBytes + ' bytes', {
					'code': 'RESPONSE_TOO_LARGE'
				} );
			}
			chunks.push( Buffer.from( item.value ) );
		}
	} finally {
		reader.releaseLock();
	}
	return Buffer.concat( chunks, total );
}

/**
* Returns a sanitized diagnostic message from a bounded JSON error response.
*
* @private
* @param {Response} response - response
* @returns {Promise<string>} diagnostic message
*/
async function responseDetail( response ) {
	var bytes;
	var value;
	var message;

	try {
		bytes = await readBoundedBody( response, limits.maxErrorBodyBytes );
	} catch ( error ) {
		await cancelBody( response );
		return '';
	}
	try {
		value = JSON.parse( new TextDecoder( 'utf-8', { 'fatal': true } ).decode( bytes ) );
	} catch ( error ) {
		return '';
	}
	if ( !value || typeof value.message !== 'string' ) {
		return '';
	}
	message = value.message.replace( /[\u0000-\u001f\u007f]+/g, ' ' ).trim();
	return message.slice( 0, limits.maxDiagnosticLength );
}

/**
* Returns a bounded HTTP error message without URL query parameters.
*
* @private
* @param {Response} response - response
* @param {URL} url - response URL
* @returns {Promise<string>} error message
*/
async function httpErrorMessage( response, url ) {
	var message = 'HTTP ' + response.status + ' from ' + url.origin + url.pathname;
	var detail = await responseDetail( response );

	if ( detail ) {
		message += ': ' + detail;
	}
	return message.slice( 0, limits.maxDiagnosticLength );
}


// MAIN //

/**
* Fetches an HTTPS resource with bounded retries, redirects, time, and bytes.
*
* @param {string|URL} url - source URL
* @param {Object} [options] - fetch options
* @returns {Promise<Object>} response metadata and bytes
*/
async function fetchBounded( url, options ) {
	var fetchImpl;
	var maxBytes;
	var maxRedirects;
	var maxRetries;
	var currentUrl;
	var headers;
	var redirects = 0;
	var attempt = 0;
	var response;
	var location;
	var resetAt;
	var wait;
	var message;

	options = options || {};
	fetchImpl = options.fetchImpl || globalThis.fetch;
	maxBytes = options.maxBytes || limits.maxHttpBytes;
	maxRedirects = options.maxRedirects === undefined ? limits.maxRedirects : options.maxRedirects;
	maxRetries = options.maxRetries || limits.maxRetries;
	currentUrl = new URL( url );
	headers = new Headers( options.headers || {} );

	while ( true ) {
		if ( currentUrl.protocol !== 'https:' ) {
			throw new HarvesterError( 'Refusing non-HTTPS URL: ' + currentUrl.href, {
				'code': 'INSECURE_URL'
			} );
		}
		try {
			response = await fetchImpl( currentUrl, {
				'method': 'GET',
				'headers': headers,
				'redirect': 'manual',
				'signal': AbortSignal.timeout( options.timeoutMs || limits.requestTimeoutMs )
			} );
		} catch ( error ) {
			if ( attempt + 1 < maxRetries ) {
				await ( options.sleep || delay )( retryDelay( null, attempt ) );
				attempt += 1;
				continue;
			}
			throw new HarvesterError( 'Request failed for ' + currentUrl.origin + ': ' + error.message, {
				'code': 'REQUEST_FAILED',
				'cause': error
			} );
		}
		if ( [301, 302, 303, 307, 308].includes( response.status ) ) {
			if ( redirects >= maxRedirects ) {
				await cancelBody( response );
				throw new HarvesterError( 'Redirect limit exceeded for ' + url, {
					'code': 'REDIRECT_LIMIT'
				} );
			}
			location = response.headers.get( 'location' );
			if ( !location ) {
				await cancelBody( response );
				throw new HarvesterError( 'Redirect response did not include Location', {
					'code': 'INVALID_REDIRECT'
				} );
			}
			currentUrl = new URL( location, currentUrl );
			if ( currentUrl.protocol !== 'https:' ) {
				await cancelBody( response );
				throw new HarvesterError( 'Redirect target must use HTTPS', {
					'code': 'INSECURE_REDIRECT'
				} );
			}
			headers = new Headers( headers );
			headers.delete( 'authorization' );
			await cancelBody( response );
			redirects += 1;
			attempt = 0;
			continue;
		}
		if ( isRateLimited( response ) || response.status >= 500 ) {
			if ( attempt + 1 < maxRetries ) {
				wait = retryDelay( response, attempt );

				await cancelBody( response );
				await ( options.sleep || delay )( wait );
				attempt += 1;
				continue;
			}
			resetAt = isRateLimited( response ) ? rateLimitReset( response ) : undefined;
			message = await httpErrorMessage( response, currentUrl );

			throw new HarvesterError( message, {
				'code': isRateLimited( response ) ? 'RATE_LIMITED' : 'REMOTE_ERROR',
				'retryable': true,
				'resetAt': resetAt
			} );
		}
		if ( !response.ok ) {
			message = await httpErrorMessage( response, currentUrl );
			throw new HarvesterError( message, {
				'code': 'HTTP_ERROR'
			} );
		}
		return {
			'bytes': await readBoundedBody( response, maxBytes ),
			'response': response,
			'url': currentUrl
		};
	}
}


// EXPORTS //

module.exports = fetchBounded;
